{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Record C06 reports absolute oral bioavailability of solifenacin as 88.0% (95% CI 75.8, 102.1) in healthy male volunteers after a 10 mg oral dose versus IV, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Record C03 reports absolute bioavailability of zolpidem as about 70% in healthy young male volunteers after a 5 mg oral dose versus IV, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Record C05 reports absolute oral bioavailability of encainide as 32 ± 7% in normal subjects versus IV, supporting F >= 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All informative numeric bioavailability records across the transferred evidence are at or above 20%, with several absolute bioavailability measurements in healthy subjects ranging from about 27% to 88%. No numeric evidence below the 20% threshold was supplied.",
  "evidence_gaps": [
    "Some records are qualitative descriptions of high oral bioavailability without numeric threshold-specific values.",
    "A few numeric records come from disease-altered populations, but the strongest absolute measurements in healthy subjects consistently support F >= 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

